export class ProjectileWeapon extends Weapon {
    /**
     * Create a projectile weapon proxy instance.
     *
     * @param {Object} views - SharedArrayBuffer views
     * @param {string} type - Weapon type
     * @param {number} index - Weapon slot index
     * @param {THREE.InstancedMesh} mesh - InstancedMesh created via physics.createMeshPool()
     * @param {Physics} physics - Physics instance reference
     * @param {Object} properties - Weapon configuration properties
     */
    constructor(views: any, type: string, index: number, mesh: THREE.InstancedMesh, physics: Physics, properties: any);
    isProjectileWeapon: boolean;
    /**
     * Automatically sync mesh position with projectile physics.
     * Set to false to manually control mesh position.
     * @type {boolean}
     */
    meshAutoUpdate: boolean;
    _meshPool: any;
    /**
     * Set projectile speed (m/s).
     * @type {number}
     */
    set speed(value: number);
    /**
     * Get projectile speed (m/s).
     * @type {number}
     */
    get speed(): number;
    /**
     * Set gravity multiplier (1.0 = normal gravity).
     * @type {number}
     */
    set gravity(value: number);
    /**
     * Get gravity multiplier (1.0 = normal gravity).
     * @type {number}
     */
    get gravity(): number;
    /**
     * Set drag coefficient (air resistance).
     * @type {number}
     */
    set drag(value: number);
    /**
     * Get drag coefficient (air resistance).
     * @type {number}
     */
    get drag(): number;
    /**
     * Set projectile lifetime in seconds.
     * @type {number}
     */
    set lifetime(value: number);
    /**
     * Get projectile lifetime in seconds.
     * @type {number}
     */
    get lifetime(): number;
    /**
     * Set area-of-effect radius (0 = no AoE).
     * @type {number}
     */
    set aoeRadius(value: number);
    /**
     * Get area-of-effect radius (0 = no AoE).
     * @type {number}
     */
    get aoeRadius(): number;
}
import { Weapon } from './Weapon.js';
